const app=document.querySelector('#app'),modal=document.querySelector('#modal');let athlete={},rides=[],plans=[],goals=[],overviewGoalId=null,logs=[],cleanup=[],anchor=Date.now(),month=new Date(),selectedDay='',query='',metric='p',comparison=['',''],importing=false,results=[],deferredInstall=null,updateWorker=null,updateRelease=null,updating=false;const state={page:'welcome',id:''};let previousView='',calorieCache=new WeakMap();let chosenPeriods=null;try{const saved=JSON.parse(localStorage.getItem('andride-periods'));if(validRange(saved?.current)&&validRange(saved?.previous))chosenPeriods=saved}catch{}
const overviewPeriods=()=>chosenPeriods||defaultPeriods(anchor);const overlayKeys=new Set(['hr','v','c']);
