async function refresh(){calorieCache=new WeakMap();athlete=(await db.get('meta','athlete'))?.value||{};rides=(await db.all('rides')).sort((a,b)=>b.start-a.start);const stale=rides.filter(r=>r.analyticsVersion!==3);if(stale.length){for(const hash of new Set(stale.map(r=>r.hash))){const file=await db.get('files',hash);if(!file)continue;try{const parsed=await decodeWorker(file.buffer,file.name);const existing=new Map(rides.map(r=>[r.id,r]));await db.transact(['rides'],tx=>{for(const r of parsed.rides)if(existing.has(r.id))tx.objectStore('rides').put({...r,customTitle:existing.get(r.id).customTitle||'',manualRoute:existing.get(r.id).manualRoute})})}catch{/* Keep stored history usable. */}}rides=(await db.all('rides')).sort((a,b)=>b.start-a.start)}plans=(await db.get('meta','plans'))?.value||[];goals=(await db.get('meta','goals'))?.value||[];overviewGoalId=(await db.get('meta','overview-goal'))?.value||null;logs=(await db.get('meta','logs'))?.value||[]}
