const rideDateTime=r=>`${date(r.start)} · ${new Date(r.start).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'})}`;
const rideTitle=r=>r.customTitle?.trim()||rideDateTime(r);
function rideCalories(r){if(!calorieCache.has(r))calorieCache.set(r,caloriesForRide(r,athlete));return calorieCache.get(r)}
const calorieText=c=>c?`${c.estimated?'≈ ':''}${num(c.value,0)}`:'—';
function periodEnergy(rs){const cs=rs.map(rideCalories);return {calories:rs.length&&cs.every(Boolean)?cs.reduce((sum,c)=>sum+c.value,0):null,caloriesEstimated:cs.some(c=>c?.estimated)}}
function card(r){const speed=Number.isFinite(r.avgSpeed),hr=Number.isFinite(r.avgHr),power=Number.isFinite(r.avgPower),calories=rideCalories(r);return `<a class="card ride-card ride-story" data-user-label href="#ride/${r.id}" aria-label="${t('Открыть поездку')} ${esc(rideTitle(r))}"><h3 class="ride-name" ${r.customTitle?'data-user-content':''}>${esc(rideTitle(r))}</h3><p class="title">${rideDateTime(r)}</p><p class="ride-story-copy">${badge(date(r.start),'date')} <span>расстояние</span> <strong>${km(r.distance)} км</strong>${speed?` <span>со средней скоростью</span> ${icon('right')} <strong>${num(r.avgSpeed*3.6)} км/ч</strong>`:''}${hr?` <span>${speed?'и пульсом':'со средним пульсом'}</span> ${icon('heart')} <strong>${num(r.avgHr,0)} уд/мин</strong>`:power?` <span>со средней мощностью</span> ${icon('power')} <strong>${num(r.avgPower,0)} Вт</strong>`:''}${!speed&&!hr&&!power?` ${icon('time')} <strong>${time(r.duration)}</strong>`:''}${calories?`, <span>потратил калорий</span> ${icon('calories')} <strong class="ride-calories">${calorieText(calories)} <span>ккал</span></strong>`:''}</p></a>`}

function empty(title='Пока нет поездок'){return `<section class="empty"><h2>${title}</h2>${img('illustration-progress','Велосипедист из пиксельных полос')}<p class="muted">Добавь оригинальный FIT с велокомпьютера. Дистанция, датчики и маршрут появятся из содержимого файла.</p>${link('Импортировать FIT','import')}<p class="muted small">Файлы и история хранятся только на этом устройстве.</p></section>`}
function monthHeader(){return `<div class="spread">${btn(icon('left'),'month-prev','circle')}<h3>${new Date(month).toLocaleDateString(locale(),{month:'long',year:'numeric'})}</h3>${btn(icon('right'),'month-next','circle')}</div>`}
function calendar(showPlans=false,smart=null){const smartDays=new Map((smart?.rows||[]).map(row=>[row.date,row]));const first=new Date(month.getFullYear(),month.getMonth(),1),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(1-offset);return `<div class="calendar">${Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(locale(),{weekday:'short'}).format(new Date(2026,9,19+i))).map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:Math.ceil((offset+new Date(month.getFullYear(),month.getMonth()+1,0).getDate())/7)*7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=day(+d),has=rides.some(r=>day(r.start)===key),smartDay=smartDays.get(key),rest=!!smartDay?.rest,plan=showPlans&&(plans.some(p=>p.date===key)||smartDay?.planned>0||smartDay?.actual>0);return `<button class="${has?'has-ride':''} ${plan?'has-plan':''} ${rest?'has-rest':''} ${d.getMonth()!==month.getMonth()?'outside':''}" data-day="${key}" aria-label="${date(+d)}${has?', есть поездка':''}${plan?', есть план':''}${rest?', день отдыха':''}${smartDay?.planned>0?', '+num(smartDay.planned,1)+' км':''}" aria-pressed="${selectedDay===key}"><i></i>${d.getDate()}</button>`}).join('')}</div>`}
function welcome(){return `<h1>Твой прогресс.<br>Из твоих FIT.</h1><p class="intro-description">Загрузи поездки с велокомпьютера и посмотри, как меняются дистанция, мощность и регулярность.</p>${img('illustration-progress','Велосипедист из пиксельных полос')}${link('Импортировать первую поездку','import')}<p class="muted small">Без аккаунта. Файлы и история остаются на этом устройстве.</p>${link('Как это работает','intro','link-button')}`}

function intro(){return `<h1>Начало работы</h1>${img('illustration-fit','Импорт FIT из пиксельных полос')}${panel('Импортируй FIT','Выбери оригинальный файл поездки с велокомпьютера. Аккаунт и подключение датчиков не нужны.')}${panel('Смотри результаты','Дистанция, графики и маршрут появятся из данных файла.')}${panel('Сохраняй историю','Данные остаются на устройстве. Резервная копия поможет перенести их или восстановить.')}${link('Выбрать FIT','import')}${link('Какие данные доступны','fit-info','link-button')}`}

function fitInfo(){return `<h1>Что есть в FIT</h1><p class="muted small">Метрики зависят от содержимого каждого файла.</p>${img('illustration-fit-content','Содержимое FIT из пиксельных полос')}${panel('Всегда проверяем файл','Дату, тип активности, структуру и доступные записи.')}${panel('Если записано устройством','Дистанция · время · скорость · высота<br>Пульс · мощность · каденс · координаты')}${panel('Порог и зоны — не обязательны','Покажем FTP, если он присутствует в файле. Без него доступны абсолютные значения.')}${link('Импортировать поездки','import')}<p class="muted small">На этом этапе не нужно вводить вес, FTP или данные датчиков вручную.</p>`}
function comparisonInsight(a,b,weekly=false){
 const fields=[['Дистанция','distance','км',.001],['Время по FIT','duration','',1],['Средняя скорость','avgSpeed','км/ч',3.6],['Набор высоты','ascent','м',1],['Калории','calories','ккал',1],['Средняя мощность','avgPower','Вт',1],['Средний пульс','avgHr','уд/мин',1],['Средний каденс','avgCadence','об/мин',1]];
 const values=fields.filter(([,k])=>(!weekly||a.count>0&&b.count>0)&&Number.isFinite(a[k])&&Number.isFinite(b[k]));
 const paragraphs=values.map(([label,k,unit,factor])=>{const x=a[k]*factor,y=b[k]*factor,d=delta(x,y);const format=(v,estimated=false)=>(estimated?'≈ ':'')+(k==='duration'?time(v):num(v,['avgPower','avgHr','avgCadence','calories'].includes(k)?0:1)+(unit?' '+unit:''));return `<p>${label}: <strong>${format(x,k==='calories'&&a.caloriesEstimated)}</strong>, раньше — <strong>${format(y,k==='calories'&&b.caloriesEstimated)}</strong>. ${d===null?`Изменение: <strong class="${x>y?'trend-up':x<y?'trend-down':''}">${num(x-y)} ${k==='duration'?'с':unit}</strong>; процент от нуля не рассчитываем.`:d===0?'Значение не изменилось.':`Разница <span class="${d>0?'trend-up':'trend-down'}">${k==='calories'&&(a.caloriesEstimated||b.caloriesEstimated)?'≈ ':''}${d>0?'↑ +':'↓ '}${num(d)}%</span>.`}</p>`});const visible=values.some(([,k])=>k==='calories')?4:3,copy=paragraphs.slice(0,visible).join('')+(paragraphs.length>visible?`<details class="fold"><summary>Все показатели сравнения</summary><div class="stack">${paragraphs.slice(visible).join('')}</div></details>`:'');
 return `<section class="card insight overview-insight"><div class="spread comparison-heading"><h2>${weekly?'Периоды в сравнении':'Последние две поездки'}</h2>${weekly?btn('Выбрать','choose-periods','link-button'):''}</div>${weekly?`<p class="basis comparison-ranges">${esc(rangeLabel(overviewPeriods().current,locale()))} ↔ ${esc(rangeLabel(overviewPeriods().previous,locale()))}</p>`:''}${!weekly?`<p class="basis"><span data-user-content>${esc(rideTitle(a))}</span> ↔ <span data-user-content>${esc(rideTitle(b))}</span>${a.customTitle||b.customTitle?`<br>${esc(rideDateTime(a))} и ${esc(rideDateTime(b))}`:''}</p>`:''}${copy||(weekly?'<p>Недостаточно поездок в выбранных периодах.</p>':'<p>В этих FIT пока нет общих числовых показателей для сравнения.</p>')}<details class="analysis-method"><summary>Как читать сравнение</summary><p class="basis">${weekly?'Сравнение выбранных периодов. Сравниваются суммы за выбранные периоды, даже если их длительность разная.':'Сравнение периодов пока недоступно — используем последнюю и предпоследнюю поездки во всей истории.'} Показаны только доступные показатели. Расчётные калории отмечены знаком ≈. Маршрут, ветер и условия могли отличаться; изменение показателей само по себе не означает улучшение или ухудшение формы.</p></details>${!weekly?link('Сравнить подробнее →','compare','link-button'):''}</section>`;
}
function goalProgress(g){const rs=rides.filter(r=>r.start<=Date.now()&&day(r.start)>=g.from&&day(r.start)<=g.to),total=totals(rs),value=g.kind==='distance'?(total.distance||0)/1000:g.kind==='duration'?(total.duration||0)/3600:total.count;return {value,unit:g.kind==='distance'?'км':g.kind==='duration'?'ч':'поездок',remaining:Math.max(0,g.target-value),percent:Math.min(100,Math.floor(value/g.target*100))}}
function overviewGoals(){const g=pickGoal(goals,overviewGoalId);if(!g)return `<div class="overview-goals">${btn(goals.length?'Выбрать цель':'Создать цель','choose-goal','link-button')}</div>`;const {value,unit,remaining,percent}=goalProgress(g);return `<section class="overview-goals" aria-label="Мои цели"><p class="goal-story"><strong>Привет,</strong> твоя цель <button type="button" class="badge date goal-name" data-action="choose-goal" aria-haspopup="dialog" title="${esc(g.title)}" data-user-content>${esc(g.title)}</button> выполнена на <span class="goal-meter" role="progressbar" aria-label="Выполнение цели" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100">${Array.from({length:10},(_,i)=>`<i class="${value/g.target*10>=i+1?'filled':''}"></i>`).join('')}</span> <strong class="accent">${percent}%</strong>. ${remaining===0?`${icon('check')}<strong class="accent">Цель выполнена</strong>`:`${icon('right')} Осталось <strong class="accent">${num(remaining,g.kind==='count'?0:1)}</strong> из ${num(g.target,0)} ${unit}`} ${icon('calendar')} до <strong>${date(g.to+'T12:00:00')}</strong></p></section>`}
function chooseOverviewGoal(){modal.innerHTML=`<h2>Выбрать цель</h2><div class="stack goal-options">${goals.map(g=>{const {percent}=goalProgress(g);return `<button type="button" class="menu-item" data-goal-option="${esc(g.id)}" aria-pressed="${g.id===overviewGoalId}"><strong data-user-content>${esc(g.title)}</strong><span>${date(g.from+'T12:00:00')} — ${date(g.to+'T12:00:00')} · ${percent}%</span></button>`}).join('')}${btn('Создать новую','new-overview-goal','button')}<button type="button" class="link-button" data-goal-cancel>Отмена</button></div>`;for(const button of modal.querySelectorAll('[data-goal-option]'))button.onclick=async()=>{try{await db.put('meta',{id:'overview-goal',value:button.dataset.goalOption});overviewGoalId=button.dataset.goalOption;modal.close();render()}catch(error){toast(error.message)}};modal.querySelector('[data-goal-cancel]').onclick=()=>modal.close();localize(modal);modal.showModal();animateDialog(modal)}
function chooseOverviewPeriods(){const ranges=overviewPeriods();modal.innerHTML=`<h2>Периоды в сравнении</h2><div class="stack period-options"><button type="button" class="menu-item" data-action="period-current"><strong>Основной период</strong><span>${esc(rangeLabel(ranges.current,locale()))}</span></button><button type="button" class="menu-item" data-action="period-previous"><strong>Период для сравнения</strong><span>${esc(rangeLabel(ranges.previous,locale()))}</span></button><button type="button" class="link-button" data-period-close>Закрыть</button></div>`;modal.querySelector('[data-period-close]').onclick=()=>modal.close();localize(modal);modal.showModal();animateDialog(modal)}
function overview(){if(!rides.length)return `<h1>Обзор</h1>${overviewGoals()}${empty()}`;const ranges=overviewPeriods(),current=withinRange(rides,ranges.current),previous=withinRange(rides,ranges.previous),a={...totals(current),...periodEnergy(current)},b={...totals(previous),...periodEnergy(previous)};return `<h1>Обзор</h1>${overviewGoals()}<div class="desktop-grid"><div class="stack"><div class="hero"><strong>${km(a.distance??0)}</strong><span>км</span></div><p class="muted small">${a.count} поездок · из импортированных FIT</p><div class="stack overview-summary"><div class="metrics">${metricCard('Время по FIT',time(a.duration))}${metricCard('Набор высоты · м',num(a.ascent,0))}</div>${comparisonInsight(a,b,true)}</div><section class="chart-wrap"><h2>${periodBars(current,ranges.current).grouped?'Дистанция за период':'Дистанция по дням'}</h2><canvas id="daily-chart" aria-label="Дистанция за выбранный период"></canvas></section></div><div class="stack"><h2>Последняя поездка</h2>${card(rides[0])}${link('Все поездки','rides','button secondary')}</div></div>`}

function rideList(){if(!rides.length)return `<h1>Поездки</h1>${empty()}`;const filtered=rides.filter(r=>(query||new Date(r.start).getFullYear()===month.getFullYear()&&new Date(r.start).getMonth()===month.getMonth()&&(!selectedDay||day(r.start)===selectedDay))&&(!query||[rideTitle(r),rideDateTime(r)].join(' ').toLowerCase().includes(query.toLowerCase())));return `<h1>Поездки</h1><form id="search" class="search-row"><input name="query" type="search" aria-label="Найти поездку" placeholder="Название или дата" value="${esc(query)}"><button class="pill light">Найти</button>${query?btn('Сбросить','clear-search','pill'):''}</form>${query?'<p class="muted small">Поиск по всей истории</p>':monthHeader()}<div class="desktop-grid ${query?'search-results-layout':''}"><div class="stack">${query?'':`${calendar()}<p class="muted small">Оранжевая дата — день с импортированной поездкой.</p>${selectedDay?btn('Показать весь месяц','clear-day','pill'):''}`}</div><div class="stack"><div class="spread"><h2>${query?'Результаты поиска':'Поездки'} · ${filtered.length}</h2>${rides.length>=2?link('Сравнить','compare','pill'):''}</div>${filtered.map(card).join('')||panel(query?'Ничего не найдено':'В этом периоде пока пусто',query?'Попробуй другое название или дату.':'Выбери другой месяц или импортируй FIT.')}</div></div>`}

function rideDetail(r,analysis=false){if(!r)return `<h1>Поездка не найдена</h1>${link('К поездкам','rides')}`;const fields=[['Мощность','p','Вт'],['Пульс','hr','уд/мин'],['Скорость','v','км/ч'],['Каденс','c','об/мин'],['Высота','h','м']],available=fields.filter(([,key])=>r.points.some(p=>Number.isFinite(p[key])));if(!available.some(f=>f[1]===metric)&&available.length)metric=available[0][1];const field=available.find(f=>f[1]===metric),gps=r.manualRoute?.enabled||r.points.some(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)),summary=[['Средняя мощность · Вт',r.avgPower],['Средний пульс · уд/мин',r.avgHr],['Набор высоты · м',r.ascent],['Каденс · об/мин',r.avgCadence]].filter(([,v])=>Number.isFinite(v));return `<a class="back-link" href="#rides">← К поездкам</a><h1 ${r.customTitle?'data-user-content':''}>${esc(rideTitle(r))}</h1>${r.customTitle?`<p class="muted small">${esc(rideDateTime(r))}</p>`:''}<div class="hero"><strong>${km(r.distance)}</strong><span>км</span></div><div class="row">${badge(time(r.duration))}${Number.isFinite(r.avgSpeed)?badge(num(r.avgSpeed*3.6)+' км/ч'):''}</div>${summary.length?`<div class="metrics">${summary.map(([label,value])=>metricCard(label,num(value,0))).join('')}</div>`:''}${energyMarkup(r,athlete)}${rides.length>=2?link('Сравнить с другой поездкой','compare','link-button'):''}<section id="workout-route" class="stack"><div class="spread"><h2>Маршрут в 3D</h2>${link('Исправить маршрут','route-edit/'+r.id,'link-button')}</div>${r.manualRoute?.enabled?'<p class="muted small">Исправленный маршрут · высота рельефа по карте. Показатели FIT не изменены.</p>':''}${gps?routeMarkup(icon):'<p class="muted small">В FIT нет GPS — маршрут недоступен.</p>'}</section>${overlayMarkup(r.points,overlayKeys)}${hrMarkup(r,athlete,rides.find(x=>x.start<r.start))}${field?`<details class="fold sensor-details"><summary>Отдельные показатели</summary><div class="stack"><div class="tabs" aria-label="Показатель графика">${available.map(([name,key])=>`<button class="pill ${metric===key?'selected':''}" data-metric="${key}" aria-pressed="${metric===key}">${name}</button>`).join('')}</div><section class="chart-wrap"><h2>${field[0]} · ${field[2]}</h2><canvas id="sensor-chart" aria-label="Столбцы показателя по времени"></canvas><output class="chart-readout">Столбец — среднее на участке времени. Нажми, чтобы увидеть исходное измерение.</output></section><div class="metrics">${metricCard('Минимум · '+field[2],num(r.points.map(p=>metric==='v'&&p.v!==null?p.v*3.6:p[metric]).filter(Number.isFinite).reduce((a,b)=>Math.min(a,b),Infinity),0))}${metricCard('Максимум · '+field[2],num(r.points.map(p=>metric==='v'&&p.v!==null?p.v*3.6:p[metric]).filter(Number.isFinite).reduce((a,b)=>Math.max(a,b),-Infinity),0))}</div></div></details>`:''}<details class="fold"><summary>Источник и доступность</summary><p class="muted small">Время: ${r.durationSource==='timer'?'по таймеру устройства':'полная длительность, включая остановки'}.<br>${Number.isFinite(r.ftp)?`FTP: ${num(r.ftp,0)} Вт.<br>`:''}Пропуски датчиков показаны разрывами.</p></details><details class="fold"><summary>Действия с поездкой</summary><section class="ride-tools" aria-label="Действия с поездкой">${btn(r.customTitle?'Изменить название':'Добавить название','rename-ride','link-button')}${btn('Скачать оригинал FIT','download-fit','link-button')}${r.manualRoute?.enabled?btn('Показать исходный GPS','original-route','link-button'):''}${btn('Удалить поездку','delete-ride','link-button danger-text')}</section></details>`}

function compare(){
 if(rides.length<2)return `<h1>Сравнить поездки</h1>${panel('Нужны две поездки','Импортируй хотя бы два FIT-файла для сравнения.')}${link('Импортировать FIT','import')}`;
 const a=rides.find(r=>r.id===comparison[0])||rides[0],b=rides.find(r=>r.id===comparison[1]&&r.id!==a.id)||rides.find(r=>r.id!==a.id);comparison=[a.id,b.id];
 const options=current=>rides.map(r=>`<option data-user-content value="${r.id}" ${r.id===current?'selected':''}>${esc(rideTitle(r))}</option>`).join('');
 const rows=rideComparison(a,b,athlete),format=(value,row,estimated=false)=>(estimated?'≈ ':'')+(row.key==='duration'?time(value*60):num(value,['avgPower','avgHr','avgCadence','calories'].includes(row.key)?0:1)+' '+row.unit);
 const items=rows.map(row=>{const same=Math.abs(row.difference)<.000001,rounded=Math.round(row.percent*10)/10,percent=Object.is(rounded,-0)?0:rounded;return `<p class="comparison-story">${row.label}: <strong>${format(row.first,row,row.firstEstimated)}</strong>, в другой поездке — <strong>${format(row.second,row,row.secondEstimated)}</strong>. ${same?'Значение не изменилось.':`Разница <span class="${row.difference>0?'trend-up':'trend-down'}">${row.firstEstimated||row.secondEstimated?'≈ ':''}${row.difference>0?'↑':'↓'} ${row.percent===null?`${num(Math.abs(row.difference))} ${row.unit}`:`${percent>0?'+':''}${num(percent)}%`}</span>.`}</p>`}).join('');
 const tableFields=[['Дистанция','distance','км',.001],['Время','duration','',1],['Калории','calories','ккал',1],['Мощность','avgPower','Вт',1],['Пульс','avgHr','уд/мин',1],['Скорость','avgSpeed','км/ч',3.6],['Набор','ascent','м',1],['Каденс','avgCadence','об/мин',1]],summaryValue=(r,key)=>key==='calories'?rideCalories(r)?.value:r[key],cell=(r,key,factor)=>key==='calories'?calorieText(rideCalories(r)):key==='duration'?time(r[key]):num(Number.isFinite(r[key])?r[key]*factor:null);
 return `<h1>Сравнить поездки</h1><label>Основная поездка<select id="compare-a">${options(a.id)}</select></label><label>Сравнить с<select id="compare-b">${options(b.id)}</select></label><section class="card insight overview-insight ride-comparison"><h2>Поездки в сравнении</h2>${items||'<p>В этих FIT пока нет общих числовых показателей для сравнения.</p>'}<details class="analysis-method"><summary>Как читать сравнение</summary><p class="basis">Показаны только доступные показатели. Расчётные калории отмечены знаком ≈. Условия, маршрут и длительность могут отличаться; разница сама по себе не означает изменение формы.</p>${rows.map(row=>`<p class="basis"><strong>${row.label}.</strong> ${row.explanation}</p>`).join('')}${rows.some(row=>row.percent===null&&row.difference!==0)?'<p class="basis">Процент от нуля не рассчитываем.</p>':''}<p class="basis comparison-context"><span data-user-content>${esc(rideTitle(a))}</span> · ${esc(date(a.start))}<br><span data-user-content>${esc(rideTitle(b))}</span> · ${esc(date(b.start))}</p></details></section><details class="fold comparison-table"><summary>Все показатели</summary><table><thead><tr><th>Показатель</th><th>A</th><th>B</th></tr></thead><tbody>${tableFields.filter(([,key])=>Number.isFinite(summaryValue(a,key))||Number.isFinite(summaryValue(b,key))).map(([label,key,unit,factor])=>`<tr><td>${label}</td><td>${cell(a,key,factor)} ${unit}</td><td>${cell(b,key,factor)} ${unit}</td></tr>`).join('')}</tbody></table></details>`;
}
function progress(){if(!rides.length)return `<h1>Прогресс</h1>${empty()}`;const total=totals(rides),best=new Map();for(const r of rides)for(const c of curve(r.points)){const v=best.get(c.seconds);if(!v||c.power>v.power)best.set(c.seconds,{...c,ride:r})}return `<div class="spread"><h1>Прогресс</h1>${link('Интеллект','intellect','pill')}</div><p class="muted small">За всё время · ${total.count} поездок из FIT</p><div class="hero"><strong>${km(total.distance)}</strong><span>км</span></div><div class="metrics">${metricCard('Всего времени',time(total.duration))}${metricCard('Набор высоты · м',num(total.ascent,0))}</div><section class="stack"><h2>По месяцам</h2><table><thead><tr><th>Месяц</th><th>км</th><th>Время</th></tr></thead><tbody>${[...new Set(rides.map(r=>day(r.start).slice(0,7)))].sort().reverse().map(key=>{const t=totals(rides.filter(r=>day(r.start).startsWith(key)));return `<tr><td>${new Date(key+'-01T12:00').toLocaleDateString(locale(),{month:'long',year:'numeric'})}</td><td>${km(t.distance)}</td><td>${time(t.duration)}</td></tr>`}).join('')}</tbody></table></section>${best.size?`<section class="stack"><h2>Кривая мощности</h2><table><thead><tr><th>Интервал</th><th>Мощность</th><th>Поездка</th></tr></thead><tbody>${[...best.values()].sort((a,b)=>a.seconds-b.seconds).map(c=>`<tr><td>${c.seconds<60?c.seconds+' с':c.seconds/60+' мин'}</td><td>${num(c.power,0)} Вт</td><td><a class="accent" href="#ride/${c.ride.id}">${date(c.ride.start)}</a></td></tr>`).join('')}</tbody></table><p class="muted small">Лучшая средняя мощность на непрерывном отрезке. Пробелы записи длиннее 5 с разделяют интервалы.</p></section>`:''}`}

function alignGoalMonth(){const g=pickGoal(goals,overviewGoalId),today=day(Date.now());if(g){const key=today<g.from?g.from:today>g.to?g.to:today;month=new Date(key+'T12:00:00')}else month=new Date();selectedDay=''}
function manualPlansMarkup(){return `${btn('Добавить тренировку','add-plan','pill light')}${plans.filter(p=>p.date.startsWith(day(+month).slice(0,7))&&(!selectedDay||p.date===selectedDay)).map(p=>{const r=rides.find(r=>r.id===p.rideId);return `<section class="card"><h3 data-user-content>${esc(p.title)}</h3><p>${date(p.date+'T12:00')} · ${p.minutes} мин в плане</p><p>${r?'Факт: '+time(r.duration)+' · '+km(r.distance)+' км':'FIT пока не привязан. Статус не считается пропуском.'}</p><button class="pill light" data-link-plan="${p.id}">${r?'Изменить связанный FIT':'Привязать FIT'}</button><details class="fold"><summary>Действия</summary><button class="link-button danger-text" data-remove-plan="${p.id}">Удалить план</button></details></section>`}).join('')||'<p class="muted small">В этом месяце нет ручных тренировок.</p>'}`}
function planPage(){return intellectMarkup({goals,activeId:overviewGoalId,rides,month,selectedDay,calendar:model=>calendar(true,model),monthHeader,manualMarkup:manualPlansMarkup,goalProgress})}

function importPage(){return `<h1>Импорт FIT</h1><p class="muted">Выбери оригинальные файлы с велокомпьютера. Можно импортировать несколько поездок сразу.</p><div class="dropzone" id="dropzone">${icon('plus')}${btn(importing?'Читаем файлы…':'Выбрать FIT','choose-fit')}<p class="muted small">Или перетащи файлы сюда<br>До 25 МБ на файл · до 50 файлов за раз</p></div><p class="muted small">Файлы обрабатываются на устройстве и не отправляются на сервер.</p>${importing?'<progress></progress>':''}<div id="import-results" aria-live="polite">${results.map(r=>`<div class="card import-status"><div>${r.ok?icon('check'):''}</div><div><h3 data-user-content>${esc(r.name)}</h3><p class="${r.error?'error':'muted'}">${esc(r.message)}</p></div></div>`).join('')}</div>${!importing&&results.some(r=>r.ok)?link('Открыть обзор','overview'):''}${logs.length?`<details class="fold"><summary>История импорта</summary><div class="stack">${logs.slice(0,8).map(l=>panel('<span data-user-content>'+esc(l.name)+'</span>',esc(l.message))).join('')}</div></details>`:''}`}

function more(){const rows=items=>items.map(([p,title,copy])=>`<a class="menu-item" href="#${p}"><strong>${title}</strong><span>${copy}</span></a>`).join('');return `<h1>Ещё</h1><section class="menu-group"><h2>Тренировки</h2>${rows([['athlete','Профиль и расчёты','Вес и пульсовые зоны']])}</section><section class="menu-group"><h2>Приложение</h2>${updateCard()}${rows([['settings','Настройки приложения','Язык, хранение и помощь'],['backup','Резервная копия','Сохранить или перенести историю'],['about','О приложении','Создатель и лицензия']])}</section><footer class="creator-footer"><p class="muted">and ride · версия 1.13</p><a href="https://www.instagram.com/mysaintdrafts/" target="_blank" rel="noopener noreferrer" aria-label="St.Drafts"><img src="./assets/st-drafts.svg" width="149" height="74" alt="St.Drafts. Design."></a><p class="muted">Приложение создано в рамках проекта St.Drafts, в котором я разрабатываю дизайн-концепции вещей, призванных упрощать повседневную жизнь и делать её более стильной.</p><p>St.Drafts <a href="https://www.instagram.com/mysaintdrafts/" target="_blank" rel="noopener noreferrer">@mysaintdrafts</a><br>Nik Koslow <a href="https://www.instagram.com/hoodbynik/" target="_blank" rel="noopener noreferrer">@hoodbynik</a></p></footer>`}

function install(){return `<h1>Установка приложения</h1>${languagePicker()}${isInstalled()?panel('Приложение установлено','Ты уже используешь установленную версию.'):''}${deferredInstall?btn('Установить приложение','install'):''}${installInstructions()}${link('Перейти к поездкам','overview')}`}
function storage(){return `<h1>Файлы и хранение</h1><div class="metrics">${metricCard('Поездок',rides.length)}${metricCard('Оригиналы · МБ',num(rides.reduce((a,r)=>a+r.fileSize,0)/1048576))}</div><p class="muted">История хранится на этом устройстве. Перед очисткой данных приложения сохрани резервную копию.</p><p class="muted small" id="storage-estimate"></p><details class="fold"><summary>Дополнительно</summary>${btn('Запросить постоянное хранение','persist','link-button')}</details>${link('Сохранить резервную копию','backup')}${link('История импорта','import','pill')}`}
function athletePage(){return `<h1>Профиль и расчёты</h1><p class="muted">Необязательные данные хранятся на этом устройстве. Они нужны только для расчётной мощности и зон, если нужных параметров нет в FIT.</p>${weatherProfileMarkup()}<form id="athlete-form"><label>Вес велосипедиста · кг<input name="weight" type="number" min="20" max="300" step="0.1" value="${athlete.weight||''}" placeholder="Например, 75"></label><label>Вес велосипеда и снаряжения · кг<input name="bikeWeight" type="number" min="3" max="80" step="0.1" value="${athlete.bikeWeight||''}" placeholder="Например, 10"></label><label>Известный максимальный пульс · уд/мин<input name="maxHr" type="number" min="80" max="240" step="1" value="${athlete.maxHr||''}" placeholder="Из теста или настроек устройства"></label><p class="muted small">Максимальный пульс этой поездки не считается физиологическим максимумом. Указанный здесь максимум заменит зоны из FIT для анализа; очисти поле, чтобы снова использовать FIT.</p><button class="button">Сохранить параметры</button><p class="error small" data-profile-error role="alert"></p></form><details class="analysis-method"><summary>Допущения расчётов</summary><p>Оценка мощности использует массу, скорость, изменение высоты и ускорение. Приняты спокойный воздух, CdA 0,40 м², Crr 0,006 и КПД трансмиссии 97%. Модель не знает ветер, езду в группе, посадку и покрытие. Калории из мощности используют эффективность 22%, с диапазоном допущений 18–25%. Оценки не используются для FTP и рекордов.</p></details>`}
function backupPage(){return `<h1>Резервная копия</h1>${panel('Сохранить историю','Копия содержит оригинальные FIT, названия поездок, исправленные маршруты, параметры расчётов, планы и цели. Храни файл у себя: он может содержать GPS-координаты.')}${btn('Скачать копию','export')}${btn('Восстановить из копии','restore','button secondary')}<p class="muted small">Восстановление добавляет новые файлы и не удаляет текущие поездки. Повторы пропускаются.</p>`}
function aboutPage(){return `<h1>О приложении</h1><section class="stack"><h2>and Ride</h2><p class="muted">История велопоездок и анализ тренировок из FIT-файлов велокомпьютера.</p><p class="muted small">Версия 1.07 · данные хранятся на этом устройстве</p></section><section class="card"><p class="small muted">Создатель</p><h2>Nik Koslow</h2><a class="creator-link" href="https://www.instagram.com/hoodbynik/" target="_blank" rel="noopener noreferrer" aria-label="Instagram создателя: @hoodbynik">Instagram · @hoodbynik ↗</a></section><section class="card"><h2>Лицензия</h2><p>Бесплатное использование и изменение с сохранением авторства Nik Koslow. Продажа приложения и услуг, основанных преимущественно на нём, ограничена Commons Clause.</p><p class="muted small">MIT + Commons Clause · исходный код доступен. Это не лицензия Open Source.</p><a href="./LICENSE.txt" target="_blank" rel="noopener">Полный текст лицензии →</a><br><a href="./THIRD_PARTY_NOTICES.txt" target="_blank" rel="noopener">Сторонние компоненты и источники →</a></section>${link('Как работает импорт FIT','fit-info','menu-item')}${link('Файлы и хранение','storage','menu-item')}`}
function updateCard(){const info=updateWorker?updateRelease:{version:'1.07',...releaseNotes},releaseDate=info?new Date(info.date+'T12:00:00').toLocaleDateString(locale(),{month:'long',year:'numeric'}):'';return `<section class="card update-card" aria-busy="${updating}"><h2>${updating?'Проверяем обновление…':updateWorker?'Доступно обновление':'Обновления приложения'}</h2><div class="update-identity"><img src="./assets/app-icon-192.png" width="96" height="96" alt="and Ride"><p><strong>and ride</strong>${info?` <span>версия</span> ${esc(info.displayVersion||info.version)}<br>${esc(releaseDate)}`:''}</p></div>${info?`<h3>Основные изменения</h3><ul>${info.changes.map(copy=>`<li>${esc(copy)}</li>`).join('')}</ul>`:`<p>Обновление загружено и готово к установке.</p>`}<button type="button" class="button full" data-action="update" ${updating?'disabled':''}>${updating?'Проверяем обновление…':updateWorker?'Обновить':'Проверить обновление'}</button></section>`}
function settings(){return `<h1>Настройки приложения</h1>${languagePicker()}${link('Файлы и хранение','storage','menu-item')}<section class="menu-group"><h2>Помощь</h2>${link('Как это работает','intro','menu-item')}${link('Какие данные доступны','fit-info','menu-item')}${!isInstalled()?link('Установка приложения','install','menu-item'):''}</section><details class="fold updates-fold" ${updateWorker?'open':''}><summary>Обновления</summary>${updateCard()}</details><p class="muted small">Часовой пояс и формат дат — по настройкам устройства.</p>`}

