function confirmBox(title,copy,yes){modal.innerHTML=`<h2>${title}</h2><p class="muted">${copy}</p><div class="row"><button class="button secondary" data-cancel>Отмена</button><button class="button danger" data-confirm>Удалить</button></div>`;modal.querySelector('[data-cancel]').onclick=()=>modal.close();modal.querySelector('[data-confirm]').onclick=async()=>{await yes();modal.close()};localize(modal);modal.showModal();animateDialog(modal)}
function formBox(title,html,onSubmit){modal.innerHTML=`<h2>${title}</h2><form>${html}<p class="error small" data-form-error role="alert"></p><div class="row"><button type="button" class="button secondary" data-cancel>Отмена</button><button class="button">Сохранить</button></div></form>`;modal.querySelector('[data-cancel]').onclick=()=>modal.close();modal.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(new FormData(e.target));modal.close();render()}catch(error){modal.querySelector('[data-form-error]').textContent=error.message}};localize(modal);modal.showModal();animateDialog(modal)}
