function decodeWorker(buffer,name){return new Promise((resolve,reject)=>{const w=new Worker(new URL('./import-worker.js',import.meta.url),{type:'module'});const timer=setTimeout(()=>{w.terminate();reject(Error('Файл читается слишком долго. Попробуй экспортировать отдельную поездку.'))},45000);w.onmessage=({data})=>{clearTimeout(timer);w.terminate();data.error?reject(Error(data.error)):resolve(data.result)};w.onerror=e=>{clearTimeout(timer);w.terminate();reject(Error(e.message||'Не удалось запустить декодер FIT. Перезагрузи приложение онлайн.'))};const copy=buffer.slice(0);w.postMessage({id:1,buffer:copy,name},[copy])})}
async function importFiles(files){if(importing)return;files=files.slice(0,50);if(!files.length)return;importing=true;results=[];go('import');render();try{for(const f of files){let entry={name:f.name};try{if(!/\.fit$/i.test(f.name))throw Error('Нужен файл с расширением .fit.');if(f.size>25*1048576)throw Error('Файл больше 25 МБ.');const buffer=await f.arrayBuffer(),result=await decodeWorker(buffer,f.name),added=await db.addImport(result,buffer,f.name);entry={...entry,ok:true,message:added?`${result.rides.length} велотренировок импортировано`:'Уже в истории · повтор пропущен'};if(added){anchor=Math.max(...result.rides.map(r=>r.start));month=new Date(anchor);selectedDay=''}}catch(error){entry={...entry,error:true,message:error.name==='QuotaExceededError'?'Недостаточно места в браузере. Сохрани резервную копию и освободи место.':error.message}}results.push(entry);logs.unshift({...entry,at:Date.now()});await db.put('meta',{id:'logs',value:logs.slice(0,100)});await refresh();if(state.page==='import')render()}localStorage.setItem('andride-started','1')}finally{importing=false;document.querySelector('#fit-input').value='';if(state.page==='import')render()}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
const base64=buffer=>{let s='';const a=new Uint8Array(buffer);for(let i=0;i<a.length;i+=8192)s+=String.fromCharCode(...a.subarray(i,i+8192));return btoa(s)};
async function exportBackup(){const files=await db.all('files');download(new Blob([JSON.stringify({format:'andride-backup',version:1,created:new Date().toISOString(),files:files.map(f=>({name:f.name,hash:f.id,data:base64(f.buffer)})),athlete,manualRoutes:rides.filter(r=>r.manualRoute).map(r=>({id:r.id,route:r.manualRoute})),rideTitles:rides.filter(r=>r.customTitle).map(r=>({id:r.id,title:r.customTitle})),plans,goals})],{type:'application/json'}),`andride-${day(Date.now())}.backup.json`);toast('Копия сохранена')}
async function restoreBackup(file){if(!file)return;if(file.size>200*1048576)throw Error('Копия больше 200 МБ.');const data=JSON.parse(await file.text());if(data.format!=='andride-backup'||data.version!==1||!Array.isArray(data.files)||data.files.length>300)throw Error('Это не поддерживаемая резервная копия and Ride.');let added=0;const prepared=[];toast('Проверяем файлы резервной копии…');for(const f of data.files){if(typeof f.name!=='string'||typeof f.data!=='string'||f.data.length>36*1048576)throw Error('Некорректный файл в копии.');const binary=atob(f.data),buffer=Uint8Array.from(binary,c=>c.charCodeAt(0)).buffer,result=await decodeWorker(buffer,f.name);if(f.hash!==result.hash)throw Error('Контрольная сумма копии не совпала.');prepared.push({result,buffer,name:f.name})}
 const routes=new Map((Array.isArray(data.manualRoutes)?data.manualRoutes:[]).map(r=>{if(typeof r.id!=='string'||!/^[a-f0-9]{64}:\d+$/.test(r.id))throw Error('Некорректный идентификатор правки маршрута.');return [r.id,validateManualRoute(r.route)]}));
 const restoredAthlete=data.athlete===undefined?null:validProfile(data.athlete||{});
 const titles=new Map((Array.isArray(data.rideTitles)?data.rideTitles:[]).filter(t=>typeof t.id==='string'&&/^[a-f0-9]{64}:\d+$/.test(t.id)&&typeof t.title==='string'&&t.title.length<=100).map(t=>[t.id,t.title.trim()]));
 const validDate=s=>typeof s==='string'&&validRange({from:s,to:s});const newPlans=(data.plans||[]).filter(p=>typeof p.id==='string'&&/^[\w-]{1,50}$/.test(p.id)&&typeof p.title==='string'&&p.title.length<=100&&validDate(p.date)&&Number.isFinite(p.minutes)&&p.minutes>0&&p.minutes<=1440).map(p=>({...p,rideId:typeof p.rideId==='string'&&/^[a-f0-9]{64}:\d+$/.test(p.rideId)?p.rideId:null}));const newGoals=(data.goals||[]).filter(g=>typeof g.id==='string'&&/^[\w-]{1,50}$/.test(g.id)&&typeof g.title==='string'&&g.title.length<=100&&['distance','duration','count'].includes(g.kind)&&Number.isFinite(g.target)&&g.target>0&&validDate(g.from)&&validDate(g.to)&&g.from<=g.to).map(g=>({...g,smart:g.smart===true&&g.kind==='distance'&&goalDays(g)>0&&goalDays(g)<=366}));
 await db.transact(['files','rides','meta'],tx=>{if(restoredAthlete)tx.objectStore('meta').put({id:'athlete',value:restoredAthlete});for(const f of prepared){if(rides.some(r=>r.hash===f.result.hash))continue;tx.objectStore('files').put({id:f.result.hash,buffer:f.buffer,name:f.name});for(const r of f.result.rides)tx.objectStore('rides').put({...r,customTitle:titles.get(r.id)||'',...(routes.has(r.id)?{manualRoute:routes.get(r.id)}:{})});added++}for(const r of rides){if(titles.has(r.id)||routes.has(r.id))tx.objectStore('rides').put({...r,...(titles.has(r.id)?{customTitle:titles.get(r.id)}:{}),...(routes.has(r.id)?{manualRoute:routes.get(r.id)}:{})})}plans=[...plans,...newPlans.filter(p=>!plans.some(x=>x.id===p.id))];goals=[...goals,...newGoals.filter(g=>!goals.some(x=>x.id===g.id))];tx.objectStore('meta').put({id:'plans',value:plans});tx.objectStore('meta').put({id:'goals',value:goals})});await refresh();if(rides.length){anchor=rides[0].start;month=new Date(anchor)}toast(`Копия восстановлена · добавлено файлов: ${added}`);render()}
async function action(a){if(a==='choose-goal')chooseOverviewGoal();if(a==='new-overview-goal'){modal.close();createGoal(true)}if(a==='choose-periods')chooseOverviewPeriods();if(a==='original-route'){const r=rides.find(r=>r.id===state.id);if(r?.manualRoute){await db.put('rides',{...r,manualRoute:{...r.manualRoute,enabled:false}});await refresh();render()}}if(a==='rename-ride'){const r=rides.find(r=>r.id===state.id);if(!r)return;formBox('Название поездки',`<label>Название<input name="title" maxlength="100" placeholder="Прогулка по Токио" value="${esc(r.customTitle||'')}"></label><p class="muted small">Оставь поле пустым, чтобы показывать дату и время поездки.</p>`,async f=>{const title=String(f.get('title')||'').trim();if(title.length>100)throw Error('До 100 символов.');await db.put('rides',{...r,customTitle:title});await refresh()})}if(a==='choose-fit'){if(!importing)document.querySelector('#fit-input').click()}if(a==='period-current'||a==='period-previous'){const key=a==='period-current'?'current':'previous';openPeriodPicker(modal,{title:key==='current'?'Основной период':'Период для сравнения',range:overviewPeriods()[key],rides,onApply:range=>{chosenPeriods={...overviewPeriods(),[key]:range};try{localStorage.setItem('andride-periods',JSON.stringify(chosenPeriods))}catch{}render()}});animateDialog(modal)}if(a==='month-prev'||a==='month-next'){month=new Date(month.getFullYear(),month.getMonth()+(a.endsWith('prev')?-1:1),1);selectedDay='';render()}if(a==='clear-search'){query='';render()}if(a==='clear-day'){selectedDay='';render()}if(a==='add-plan')createPlan();if(a==='add-goal')createGoal();if(a==='download-fit'){const r=rides.find(r=>r.id===state.id),f=r&&await db.get('files',r.hash);if(f)download(new Blob([f.buffer]),f.name)}if(a==='delete-ride')confirmBox('Удалить поездку?','Она исчезнет из локальной истории. Сначала можно скачать исходный FIT.',async()=>{await db.removeRide(state.id);await refresh();go('rides')});if(a==='export')await exportBackup();if(a==='restore')document.querySelector('#backup-input').click();if(a==='install'&&deferredInstall){await deferredInstall.prompt();deferredInstall=null;render()}if(a==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'Постоянное хранение разрешено':'Браузер не предоставил постоянное хранение. Используй резервную копию.')}if(a==='update'){
 if(updating)return;if(importing){toast('Дождись завершения импорта перед обновлением.');return;}
 const r=await navigator.serviceWorker?.getRegistration();if(!r){toast('Открой приложение по HTTPS для обновлений.');return;}
 updating=true;render();try{const worker=await checkForUpdate(r);if(worker){updateWorker=worker;toast('Устанавливаем обновление…');worker.postMessage('ACTIVATE_UPDATE')}else toast('Установлена последняя версия.')}finally{updating=false;render()}
 }if(a==='activate-update'&&updateWorker){if(importing)toast('Дождись завершения импорта перед обновлением.');else updateWorker.postMessage('ACTIVATE_UPDATE')}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-day],[data-metric],[data-overlay],[data-link-plan],[data-remove-plan],[data-remove-goal],[data-edit-goal],[data-smart-goal]');if(!el)return;try{if(el.dataset.editGoal||el.dataset.smartGoal){const g=goals.find(g=>g.id===(el.dataset.editGoal||el.dataset.smartGoal));if(g)createGoal(false,el.dataset.smartGoal?{...g,smart:true}:g)}if(el.dataset.overlay){const k=el.dataset.overlay;overlayKeys.has(k)?overlayKeys.delete(k):overlayKeys.add(k);render()}if(el.dataset.action)await action(el.dataset.action);if(el.dataset.day){selectedDay=selectedDay===el.dataset.day?'':el.dataset.day;render()}if(el.dataset.metric){metric=el.dataset.metric;render();document.querySelector('.sensor-details')?.setAttribute('open','')}if(el.dataset.linkPlan){const p=plans.find(p=>p.id===el.dataset.linkPlan);formBox('Связать с поездкой',`<label>FIT-поездка<select name="rideId"><option value="">Не привязывать</option>${rides.map(r=>`<option data-user-content value="${r.id}" ${p.rideId===r.id?'selected':''}>${esc(rideTitle(r))}</option>`).join('')}</select></label>`,async f=>{p.rideId=f.get('rideId')||null;await db.put('meta',{id:'plans',value:plans})})}for(const kind of ['plan','goal']){const id=el.dataset[kind==='plan'?'removePlan':'removeGoal'];if(id)confirmBox('Удалить '+(kind==='plan'?'план':'цель')+'?','Импортированные поездки сохранятся.',async()=>{if(kind==='plan'){plans=plans.filter(p=>p.id!==id);await db.put('meta',{id:'plans',value:plans})}else{goals=goals.filter(g=>g.id!==id);await db.put('meta',{id:'goals',value:goals});if(overviewGoalId===id){overviewGoalId=pickGoal(goals,null)?.id||null;await db.put('meta',{id:'overview-goal',value:overviewGoalId})}if(state.page==='intellect')alignGoalMonth()}render()})}}catch(error){toast(error.message)}});
document.querySelector('#fit-input').onchange=e=>importFiles([...e.target.files]).catch(e=>toast(e.message));document.querySelector('#backup-input').onchange=async e=>{try{await restoreBackup(e.target.files[0])}catch(error){toast('Не удалось восстановить: '+error.message)}finally{e.target.value=''}};
