async function setupServiceWorker(){if(!('serviceWorker' in navigator))return;if(['localhost','127.0.0.1','[::1]'].includes(location.hostname)){for(const r of await navigator.serviceWorker.getRegistrations())if(r.scope.startsWith(new URL('./',location.href).href.split('#')[0]))await r.unregister();if('caches' in window)for(const key of await caches.keys())if(key.startsWith('andride-'))await caches.delete(key);return;}const controlled=!!navigator.serviceWorker.controller;const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});if(!reg)return;watchUpdates(reg,async worker=>{updateWorker=worker;updateRelease=null;toast('Доступно обновление');if(['settings','more'].includes(state.page)&&!updating&&!importing)render();const info=await getReleaseInfo(worker);if(updateWorker!==worker)return;updateRelease=info;if(['settings','more'].includes(state.page)&&!updating&&!importing)render()},error=>toast(error.message));let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled&&!reloading){reloading=true;location.reload()}})}
async function start(){if(needsInstallation()){render();setupServiceWorker().catch(()=>{});return;}try{await db.removeMeta('apple-health');localStorage.removeItem('andride-health-seen');const oldURL=new URL(location.href);if(['health','health-intro'].includes(oldURL.hash.slice(1))||oldURL.searchParams.has('health-token')){for(const key of ['health-token','health-status','result','errorMessage'])oldURL.searchParams.delete(key);oldURL.hash='more';history.replaceState(null,'',oldURL.pathname+oldURL.search+oldURL.hash)}await refresh();if(rides.length){anchor=rides[0].start;month=new Date(anchor)}render();}catch(error){app.innerHTML=`<main class="shell content"><h1>Не удалось открыть хранилище</h1><p class="muted">${esc(error.message)}. Разреши хранение данных сайта или открой обычное окно браузера.</p><button class="button" onclick="location.reload()">Повторить</button></main>`;return}setupServiceWorker().catch(()=>{/* Offline caching is optional; IndexedDB and the current page remain usable. */})}
